'use strict';
let D;const $=s=>document.querySelector(s), cats=['Kills','Aces','Blocks','Digs','Assists'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v==null?'—':Number(v).toLocaleString('en-US');
const serial=s=>{const [m,d,y]=String(s).split('/').map(Number);return new Date(y<100?2000+y:y,m-1,d).getTime()};
const date=s=>new Date(serial(s)).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const total=rows=>cats.map((_,i)=>{const v=rows.map(s=>s.values[i]).filter(v=>v!=null);return v.length?v.reduce((a,b)=>a+b,0):null});
const route=(page,params={})=>'#'+page+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
const pByName=n=>D.players.find(p=>p.name===n), pLink=n=>pByName(n)?route('player',{id:pByName(n).id}):'#players';
const initial=n=>n.split(' ').filter(Boolean).map(s=>s[0]).slice(0,2).join('');
const statstrip=v=>`<div class="stat-strip">${cats.map((c,i)=>`<div><strong>${fmt(v[i])}</strong><span>${c}</span></div>`).join('')}</div>`;
const source=(url,label='View Results')=>url&&/^https:\/\/www\.aukssports\.com\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';
const getState=()=>{const [page='home',query='']=(location.hash.slice(1)||'home').split('?');return {page,q:new URLSearchParams(query)}};
function options(vals,current,allLabel){return (allLabel?`<option value="">${allLabel}</option>`:'')+vals.map(v=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(v)}</option>`).join('')}
function select(label,key,values,current,all){return `<div class="field"><label for="${key}">${label}</label><select id="${key}" data-filter="${key}">${options(values,current,all)}</select></div>`}
function search(label,value){return `<div class="field search"><label for="search">${label}</label><input type="search" id="search" data-filter="search" placeholder="${label}" value="${esc(value)}" autocomplete="off"></div>`}
function years(){return [...new Set(D.games.map(g=>g.season))].sort((a,b)=>b-a)}
function classYears(){return [...new Set(D.players.map(p=>p.year))].sort((a,b)=>(a==='Unknown'?9999:a)-(b==='Unknown'?9999:b))}
function currentJersey(name){const year=Math.max(...D.roster.map(r=>r.season));return D.roster.find(r=>r.season===year&&r.name===name&&r.role!=='Manager')?.jersey||'';}
function jerseyMark(name){const jersey=currentJersey(name);return jersey?`<span class="jersey-mark" aria-label="Current jersey number ${esc(jersey)}"><small>NO.</small><strong>${esc(jersey)}</strong></span>`:`<span class="alumni-mark" aria-label="${esc(name)} initials"><small>${Number(pByName(name)?.year)<=Math.max(...D.roster.map(r=>r.season))?'ALUM':'ARCHIVE'}</small><strong>${esc(initial(name))}</strong></span>`;}
function playerStatstrip(values){const selected=Number(getState().q.get('stat')??-1);return `<div class="stat-strip player-stat-strip">${cats.map((c,i)=>`<button type="button" data-player-stat="${i}" aria-label="Rank games by ${c.toLowerCase()}" aria-pressed="${selected===i}"><strong>${fmt(values[i])}</strong><span>${c}</span></button>`).join('')}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-player-stat]');if(!b)return;const {page,q}=getState();if(page!=='player')return;const value=b.dataset.playerStat;const seasonOpen=!!document.querySelector('.season-breakdown[open]');const focusIndex=[...document.querySelectorAll('[data-player-stat]')].indexOf(b);if(value==='all')q.delete('stat');else q.set('stat',value);history.replaceState(null,'',route(page,Object.fromEntries(q)));render(false);if(seasonOpen)document.querySelector('.season-breakdown').open=true;document.querySelectorAll('[data-player-stat]')[focusIndex]?.focus({preventScroll:true});});
function playerStatStory(rows,selected){if(selected<0)return 'Tap any statistic to highlight it and rank the games below.';const valid=rows.filter(r=>r.values[selected]!=null);if(!valid.length)return `No ${cats[selected].toLowerCase()} reported in the selected seasons.`;const best=Math.max(...valid.map(r=>r.values[selected]));const leaders=valid.filter(r=>r.values[selected]===best);return `<strong>${fmt(best)}</strong><span><b>Best recorded ${cats[selected].toLowerCase()}</b><small>${leaders.length===1?esc(leaders[0].opponent)+' · '+date(leaders[0].date):leaders.length+' games tied'} · ${getState().q.get('season')?'selected season':'all seasons'}</small></span>`;}
function currentRosterDetail(name){const year=Math.max(...D.roster.map(r=>r.season)),r=D.roster.find(r=>r.season===year&&r.name===name&&r.role!=='Manager');return r?`<small class="current-player-detail">${r.jersey?'#'+esc(r.jersey)+' · ':''}${r.grade?'Grade '+esc(r.grade)+' · ':''}${year} roster</small>`:'';}
function playerCard(p){return `<a class="card player-card" href="${pLink(p.name)}"><div class="top">${jerseyMark(p.name)}<div><h3>${esc(p.name)}</h3>${currentRosterDetail(p.name)}<small>${p.year==='Unknown'?'Graduation year unknown':'Class of '+p.year}</small></div><span class="arrow" aria-hidden="true">↗</span></div>${statstrip(p.values)}</a>`}
function gameCard(g){const dt=new Date(serial(g.date));return `<a class="game-card" href="${route('game',{id:g.id})}"><div class="game-date"><b>${dt.toLocaleDateString('en-US',{month:'short',day:'numeric'})}</b>${g.season}</div>${opponentMark(g.opponent)}<div class="game-body"><h3>${g.homeAway==='H'?'vs':'at'} ${esc(g.opponent)}</h3><small>${esc(g.phase)} · ${g.entries?'Player stats available':'Score only · player stats missing'}</small></div><div class="score">${esc(g.score||'—')} <span class="badge ${g.result==='L'?'loss':''}">${esc(g.result||'—')}</span></div><span class="arrow" aria-hidden="true">↗</span></a>`}
function head(title,intro,eyebrow='ARCHMERE VOLLEYBALL'){return `<div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1>${intro?`<p class="intro">${intro}</p>`:''}`}
function note(){return `<p class="note">These are documented subtotals from available results. A dash means unreported—not zero. Published player rows do not establish games played.</p>`}
function home(){const year=Math.max(...D.roster.map(r=>r.season)),first=Math.min(...D.games.map(g=>g.season));const gs=D.games.filter(g=>g.season===year).sort((a,b)=>serial(b.date)-serial(a.date)),W=gs.filter(g=>g.result==='W').length,L=gs.filter(g=>g.result==='L').length;
 const roster=D.roster.filter(r=>r.season===year&&r.role!=='Manager'),seasonRows=D.stats.filter(s=>s.season===year);
 const leader=i=>roster.map(r=>({r,v:seasonRows.filter(s=>s.name===r.name).reduce((a,s)=>a+(s.values[i]||0),0)})).sort((a,b)=>b.v-a.v)[0];
 const row=g=>{const d=new Date(serial(g.date));return `<a class="row" href="${route('game',{id:g.id})}"><span class="when"><span>${d.toLocaleDateString('en-US',{month:'short'})}</span><b>${d.getDate()}</b></span>${crest(g.opponent)}<span class="what"><b>${g.homeAway==='H'?'vs':'at'} ${esc(g.opponent)}</b><small>${g.entries?'Box score':'Score only · player stats to come'}</small></span>${scoreBadge(g)}</a>`};
 return `<div class="home-v2"><section class="hp-hero bleed"><span class="slant" aria-hidden="true"></span><span class="bg-word" aria-hidden="true">Auks</span><div class="wrap"><div><span class="label">Archmere Academy · Girls varsity</span><h1>Auks<br><em>Volleyball</em></h1><p class="script">Let's go Auks</p><div class="hero-cta"><a class="btn primary" href="#schedule">Season schedule →</a><a class="btn ghost-btn" href="#players">Find a player</a></div></div><div class="record"><b>${W}<i>–</i>${L}</b><small>${year} record</small><a href="${route('season',{year})}">Season details →</a></div></div></section><div class="stripe bleed"></div>${nextMatch()}
 <div class="grid-2"><section class="block"><div class="sec-head"><h2>Latest results</h2><a href="${route('games',{season:year})}">All results →</a></div><div class="list">${gs.slice(0,4).map(row).join('')||'<p class="empty">No results yet this season.</p>'}</div></section>
 <section class="block"><div class="sec-head"><h2>${year} leaders</h2><a href="#records">Records →</a></div><div class="leaders">${[0,3,4,1].map(i=>{const l=leader(i);return l&&l.v?`<a class="leader" href="${pLink(l.r.name)}"><span class="label">${cats[i]}</span><b>${fmt(l.v)}</b><span>${esc(l.r.name)}</span><small>${l.r.jersey?'#'+esc(l.r.jersey)+' · ':''}Grade ${esc(l.r.grade)}</small><span class="num" aria-hidden="true">${esc(l.r.jersey||'')}</span></a>`:''}).join('')}</div></section></div>
 ${milestonesBlock()}<section class="block"><div class="sec-head"><h2>The archive</h2></div><div class="quick"><a href="#seasons"><span class="label">Seasons</span><b>${first}–${year}</b><small>${year-first+1} seasons</small></a><a href="#players"><span class="label">Players</span><b>${D.players.length}</b><small>Find an Auk</small></a><a href="#records"><span class="label">Records</span><b>Top 10</b><small>All-time leaders</small></a></div></section>
 <section class="block"><div class="sec-head"><h2>Through the years</h2><a href="#players">All classes →</a></div><div class="chips">${classYears().filter(y=>y!=='Unknown').sort((a,b)=>b-a).slice(0,8).map(y=>`<a class="chip" href="${route('players',{year:y})}">Class of <b>${y}</b></a>`).join('')}</div></section>
 <p class="note">Reviewed records as of ${esc(D.updated)}. Historical statistics may be incomplete. <a href="#about">Sources &amp; coverage</a></p></div>`}
function players(q){let list=D.players.filter(p=>(!q.get('year')||String(p.year)===q.get('year'))&&(!q.get('search')||p.name.toLowerCase().includes(q.get('search').toLowerCase())));const sort=q.get('sort')||'Name';list.sort(sort==='Name'?(a,b)=>a.name.localeCompare(b.name):(a,b)=>(b.values[cats.indexOf(sort)]??-1)-(a.values[cats.indexOf(sort)]??-1));return `<div class="directory-heading"><div><div class="eyebrow">THE AUKS / PLAYER ARCHIVE</div><h1>${q.get('year')?'Class of '+esc(q.get('year')):'Players'}</h1><p>Find a familiar name. Explore their numbers.</p></div><div class="directory-seal"><strong>${list.length}</strong><span>${list.length===1?'PLAYER':'PLAYERS'}</span></div></div><div class="tools">${search('Search player names',q.get('search'))}${select('Graduation year','year',classYears(),q.get('year'),'All classes')}${select('Sort by','sort',['Name',...cats],sort)}</div><p class="count">${list.length} ${list.length===1?'player':'players'} · Tap a name to open their record</p><div class="player-grid">${list.map(playerCard).join('')}</div>${!list.length?'<p class="empty">No players match. Try another name or graduation year.</p>':''}${note()}`}
let teamLogos={};
function opponentMark(name){const logo=teamLogos[name];if(logo?.sprite){const b=logo.sprite,k=Math.min(44/b.width,44/b.height);return `<span class="opponent-mark" aria-hidden="true"><span class="opponent-banner" style="display:block;width:${b.width*k}px;height:${b.height*k}px;background-image:url('${esc(logo.file)}');background-size:${b.fullWidth*k}px ${b.fullHeight*k}px;background-position:${-b.x*k}px ${-b.y*k}px;${b.clip?'clip-path:'+b.clip+';':''}"></span></span>`;}const letters=name.replace(/\(Inactive\)\s*/,'').split(' ').filter(w=>!['HS','School','Academy','(PA)'].includes(w)).slice(0,2).map(w=>w[0]).join('');return `<span class="opponent-mark" aria-hidden="true"><span class="opponent-initials" ${logo?'hidden':''}>${esc(letters)}</span>${logo?`<img src="${esc(logo.file)}" alt="" width="44" height="44" loading="lazy">`:''}</span>`}
function playerMatch(s){const g=D.games.find(g=>g.id===s.id);const result=g?.result;return `<article class="match-card"><div class="match-meta"><time>${date(s.date)}</time><span>${esc(s.phase)}${g?.homeAway==='H'?' · Home':g?.homeAway==='A'?' · Away':''}</span></div><div class="match-opponent">${opponentMark(s.opponent)}<h3>${esc(s.opponent)}</h3><div class="match-result ${result==='L'?'lost':''}"><span>${result==='W'?'WIN':result==='L'?'LOSS':'RESULT'}</span><strong>${esc(g?.score||'—')}</strong></div></div><div class="match-numbers" aria-label="Player statistics">${playerStatstrip(s.values)}</div><div class="match-actions"><a href="${route('game',{id:s.id})}">Game details <span aria-hidden="true">→</span></a>${source(s.source,'View Results')}</div></article>`}
function personalBests(rows,season){return `<details class="personal-bests" open><summary>Best recorded games <span>${season?esc(season)+' season':'All seasons'}</span></summary><p class="best-intro">Highest published single-game totals in this selection. Tap a result to open its box score.</p><div class="best-grid">${cats.map((cat,i)=>{const known=rows.filter(r=>r.values[i]!=null),best=known.length?Math.max(...known.map(r=>r.values[i])):null,ties=known.filter(r=>r.values[i]===best).sort((a,b)=>serial(b.date)-serial(a.date));const link=r=>`<a href="${route('game',{id:r.id})}"><b>${esc(r.opponent)}</b><small>${date(r.date)} <span aria-hidden="true">↗</span></small></a>`;return `<div class="best-card"><div class="best-stat"><span>${cat}</span><strong>${fmt(best)}</strong></div>${ties.length?link(ties[0]):'<p class="quiet">Not reported</p>'}${ties.length>1?`<details class="best-ties"><summary>${ties.length-1} more game${ties.length>2?'s':''} tied</summary>${ties.slice(1).map(link).join('')}</details>`:''}</div>`}).join('')}</div></details>`;}
function coveragePanel(gs){const available=gs.filter(g=>g.entries).length,missing=gs.length-available,season=gs[0]?.season;return `<section class="coverage-panel" aria-label="Statistics coverage"><div><span>RESULTS ON FILE</span><strong>${gs.length}</strong></div><div><span>WITH PLAYER STATS</span><strong>${available}</strong></div><div><span>WITHOUT PLAYER STATS</span><strong>${missing}</strong></div><p>Coverage of archived results, not a guarantee of a complete season.${missing?` <a href="${route('games',{season,coverage:'Missing player stats'})}">See ${missing} result${missing===1?'':'s'} missing stats ↗</a>`:''}</p></section>`;}
function seasonLeaders(rows,year){const names=[...new Set(rows.map(r=>r.name))],players=names.map(name=>({name,values:total(rows.filter(r=>r.name===name))}));return `<section class="section" id="season-leaders"><div class="archive-index-title"><h2>Season leaders</h2><span>DOCUMENTED TOTALS</span></div><div class="season-leader-grid">${cats.map((c,i)=>{const reported=players.filter(p=>p.values[i]!=null),max=reported.length?Math.max(...reported.map(p=>p.values[i])):null,leaders=reported.filter(p=>p.values[i]===max);return `<div class="season-leader-card"><span>${c}</span><strong>${fmt(max)}</strong>${leaders.map(p=>`<a href="${route('player',{id:pByName(p.name)?.id,season:year})}">${esc(p.name)} ↗</a>`).join('')||'<small>No published stats</small>'}${leaders.length>1?'<small>Tied leaders</small>':''}</div>`}).join('')}</div></section>`;}
document.addEventListener('click',e=>{const button=e.target.closest('[data-season-jump]');if(button)document.getElementById(button.dataset.seasonJump)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});
function player(q){const p=D.players.find(p=>p.id===q.get('id'));if(!p)return missing('player');const rows=D.stats.filter(s=>s.name===p.name).sort((a,b)=>serial(b.date)-serial(a.date));const seasons=[...new Set([...rows.map(r=>r.season),...D.roster.filter(r=>r.name===p.name).map(r=>r.season)])].sort((a,b)=>b-a);const selected=cats[Number(q.get('stat'))]&&q.has('stat')?Number(q.get('stat')):-1;const visible=rows.filter(s=>!q.get('season')||String(s.season)===q.get('season'));if(selected>=0)visible.sort((a,b)=>(b.values[selected]??-1)-(a.values[selected]??-1)||serial(b.date)-serial(a.date));return `<div class="player-page"><a class="back" href="${route('players',{year:p.year})}">← ${p.year==='Unknown'?'All players':'Class of '+p.year}</a></div><section class="player-hero bleed" data-word="${esc(p.name.split(' ').pop())}"><div class="wrap"><span class="jersey ${currentJersey(p.name)?'':'alum'}" aria-label="${currentJersey(p.name)?'Jersey number '+esc(currentJersey(p.name)):esc(p.name)+' initials'}">${esc(currentJersey(p.name)||initial(p.name))}</span><div><span class="label">${(()=>{const r=D.roster.filter(r=>r.name===p.name).sort((a,b)=>b.season-a.season)[0];const cur=r&&r.season===Math.max(...D.roster.map(x=>x.season));return [cur&&r.jersey?'#'+esc(r.jersey):'',cur&&r.grade?'Grade '+esc(r.grade):'',p.year==='Unknown'?'Graduation year unknown':'Class of '+p.year].filter(Boolean).join(' · ')})()}</span><h1>${esc(p.name)}</h1><p>${esc(seasons.length?seasons.slice().reverse().join(' · ')+(seasons.length===1?' season':' seasons'):'Roster record')}</p>${typeof playerMilestones==='function'&&playerMilestones(p.name)?`<div class="ms-chips">${playerMilestones(p.name)}</div>`:''}</div></div></section><div class="stripe bleed"></div><div class="player-body"><section class="player-career" aria-label="Career totals"><h2>Career totals</h2>${playerStatstrip(p.values)}<p>Tap a number to explore that stat. <a href="#about">Coverage notes</a></p></section><details class="season-breakdown"><summary>Season totals <span>${seasons.length} seasons</span></summary><div class="season-grid">${seasons.map(y=>{const ss=rows.filter(r=>r.season===y);return `<div class="card season-card"><h3><a href="${route('season',{year:y})}">${y} season →</a></h3>${playerStatstrip(total(ss))}<small>${ss.length} published stat entries</small></div>`}).join('')}</div></details><section class="player-game-section"><div class="section-head"><h2>Game by game</h2><span class="quiet">${visible.length} stat entries</span></div><div class="log-filter">${select('Season','season',seasons,q.get('season'),'All seasons')}<p>${selected<0?'Newest first':'Highest '+cats[selected].toLowerCase()+' first'} · A dash means unreported.</p></div>${personalBests(visible,q.get('season'))}<div class="stat-switch player-stat-switch" role="group" aria-label="Rank player games"><button type="button" data-player-stat="all" aria-pressed="${selected<0}">Newest</button>${cats.map((c,i)=>`<button type="button" data-player-stat="${i}" aria-pressed="${selected===i}">${c}</button>`).join('')}</div><div class="stat-story" aria-live="polite">${playerStatStory(visible,selected)}</div><div class="match-list ranked-matches">${visible.map(playerMatch).join('')}</div>${!visible.length?'<p class="empty">No published game stats are available for this season.</p>':''}</section><details class="player-source-note"><summary>About this player’s records</summary><p>${esc(p.note)}</p><p>Totals include available published statistics. Missing stats are not counted as zero. Stat entries do not establish games played.</p><p>Opponent marks identify schools; they may differ from historical logos. Initials appear where a logo is unavailable.</p></details></div>`}

function games(q){const list=D.games.filter(g=>(!q.get('season')||String(g.season)===q.get('season'))&&(!q.get('search')||g.opponent.toLowerCase().includes(q.get('search').toLowerCase()))&&(!q.get('phase')||g.phase===q.get('phase'))&&(q.get('coverage')!=='Missing player stats'||!g.entries)).sort((a,b)=>serial(b.date)-serial(a.date));return `<div class="games-heading"><div class="eyebrow">THE AUKS / MATCH ARCHIVE</div><h1>Game center</h1><p>Scores, box scores, and the official results behind them.</p><span class="games-heading-tag">${list.length} RESULTS ON FILE</span></div><div class="tools">${search('Search opponents',q.get('search'))}${select('Season','season',years(),q.get('season'),'All seasons')}${select('Competition','phase',['Regular','Postseason'],q.get('phase'),'All games')}${select('Coverage','coverage',['Missing player stats'],q.get('coverage'),'All results')}</div><p class="count">${list.length} results · ${list.filter(g=>g.entries).length} with player stats · ${list.filter(g=>!g.entries).length} without · Newest first</p><div class="game-list">${list.map(gameCard).join('')}</div>${!list.length?'<p class="empty">No games match these filters.</p>':''}`}
function boxRows(rows,selected=-1){
 const sorted=[...rows].sort((a,b)=>selected<0?a.name.localeCompare(b.name):(b.values[selected]??-1)-(a.values[selected]??-1)||a.name.localeCompare(b.name));
 return sorted.map((r,index)=>`<div class="box-player" style="--row-delay:${Math.min(index,6)*35}ms"><a href="${pLink(r.name)}"><span>${selected>=0&&r.values[selected]!=null?`<small class="stat-rank">${1+rows.filter(x=>(x.values[selected]??-1)>r.values[selected]).length}</small>`:''}<span class="box-player-identity">${esc(r.name)}${currentRosterDetail(r.name)}</span></span><span aria-hidden="true">↗</span></a><div class="stat-strip">${cats.map((c,i)=>`<div class="stat-cell ${selected===i?'is-selected':''} ${selected>=0&&selected!==i?'is-muted':''}"><strong>${fmt(r.values[i])}</strong><span>${c}</span></div>`).join('')}</div></div>`).join('');
}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-box-stat]');if(!button)return;
 const panel=button.closest('.box-explorer'),selected=button.dataset.boxStat==='all'?-1:Number(button.dataset.boxStat);
 const rows=D.stats.filter(s=>s.id===panel.dataset.game);
 panel.querySelectorAll('[data-box-stat]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
 panel.querySelector('.box-players').innerHTML=boxRows(rows,selected);
 const story=panel.querySelector('.stat-story');
 if(selected<0){story.textContent='Tap a stat to see this match’s leaders.';return;}
 const reported=rows.filter(r=>r.values[selected]!=null),max=Math.max(0,...reported.map(r=>r.values[selected]));
 const leaders=reported.filter(r=>r.values[selected]===max);
 story.innerHTML=!reported.length?`No ${cats[selected].toLowerCase()} were reported for this match.`:max===0?`All reported ${cats[selected].toLowerCase()} totals are zero.`:`<strong>${max}</strong><span><b>${leaders.map(r=>esc(r.name)).join(' & ')}</b><small>${leaders.length>1?'Tied for the match lead in':'Match leader in'} ${cats[selected].toLowerCase()}</small></span>`;
});
function game(q){
 const g=D.games.find(g=>g.id===q.get('id'));if(!g)return missing('game');
 const rows=D.stats.filter(s=>s.id===g.id).sort((a,b)=>a.name.localeCompare(b.name));
 const issues=D.issues.filter(i=>String(i.id)===String(g.id));
 const sets=(g.sets||[]).filter(Boolean),score=(g.score||'').split(/[-–:]/);
 const label=g.result==='W'?'Auks take the match':g.result==='L'?'Match final':'From the match archive';
 return `<article class="game-report"><a class="back" href="${route('games',{season:g.season})}">← ${g.season} schedule</a>
 <div class="result-heading"><div class="match-dateline"><span>THE MATCH BOOK</span><span>${esc(g.season)} / GIRLS VARSITY</span></div>
 <h1 class="report-title">${label}<span>.</span></h1>
 <p class="report-date">${date(g.date)} <span>·</span> ${esc(g.phase)} <span>·</span> ${g.homeAway==='H'?'At Archmere':'Away match'}</p></div>
 <section class="match-scorecard" aria-label="Match result">
 <div class="final-label">${g.result?'FINAL SCORE':'RECORDED RESULT'}</div>
 <div class="match-teams">
 <div class="match-team ${g.result==='W'?'match-winner':''}"><div class="team-crest"><img src="archmere-auks.jpg" alt="Archmere Auks logo"></div><h2>Archmere</h2><span class="team-caption">AUKS</span><strong class="team-score">${esc(score[0]||'—')}</strong>${g.result==='W'?'<span class="winner-label">WIN</span>':''}</div>
 <span class="versus">VS</span>
 <div class="match-team ${g.result==='L'?'match-winner':''}"><div class="team-crest">${opponentMark(g.opponent)}</div><h2>${esc(g.opponent)}</h2><span class="team-caption">${g.homeAway==='H'?'VISITOR':'HOME TEAM'}</span><strong class="team-score">${esc(score[1]||'—')}</strong>${g.result==='L'?'<span class="winner-label">WIN</span>':''}</div>
 </div>
 <div class="scorecard-foot"><span>${sets.length?sets.length+' sets played':'Varsity volleyball'}</span>${source(g.url,'Official results')}</div></section>
 <section class="report-sets"><div class="report-section-title"><span>01</span><h2>Set by set</h2></div>${sets.length?`<div class="set-recap">${sets.map((v,i)=>{const n=String(v).split(/[-–:]/),won=Number(n[0])>Number(n[1]);return `<div class="recap-set"><span>SET ${i+1}</span><strong>${esc(v)}</strong><small>${won?'Archmere':Number(n[1])>Number(n[0])?esc(g.opponent):'Recorded score'}</small></div>`}).join('')}</div><p class="set-key">Scores listed Archmere first.</p>`:'<p class="archive-empty">Set scores aren’t listed in the official results for this match.</p>'}</section>
 <section class="report-box"><div class="report-section-title"><span>02</span><h2>The box score</h2></div><p class="box-subtitle">Archmere player statistics</p>
 ${rows.length?`<div class="box-explorer" data-game="${esc(g.id)}"><div class="stat-switch" role="group" aria-label="Rank players by statistic"><button type="button" data-box-stat="all" aria-pressed="true">All stats</button>${cats.map((c,i)=>`<button type="button" data-box-stat="${i}" aria-pressed="false">${c}</button>`).join('')}</div><div class="stat-story" aria-live="polite">Tap a stat to see this match’s leaders.</div><div class="box-players">${boxRows(rows)}</div><p class="bar-key">Tap a category to rank players. A dash means unreported, not zero.</p></div>`:'<div class="archive-empty"><h3>No player stats published</h3><p>The match result is on record. Individual stats weren’t available on the official results page.</p></div>'}
 <details class="box-notes"><summary>About these statistics</summary>${note()}</details></section>
 ${issues.length?`<details class="box-notes"><summary>Source notes for this match (${issues.length})</summary><a class="button" href="#review">Review questioned results →</a>${issues.map(i=>`<div class="note"><b>${esc(i.name)}</b><p>${esc(i.reason)}</p><p>Published text: ${esc(i.raw)}</p></div>`).join('')}</details>`:''}
 ${resolvedReviews((D.resolvedIssues||[]).filter(i=>String(i.id)===String(g.id)))}
 <a class="report-next" href="${route('games',{season:g.season})}"><span>BACK TO THE SEASON</span><strong>More from ${g.season} <span>→</span></strong></a></article>`;
}
function records(q){const scope=q.get('scope')||'Career',cat=q.get('category')||'Kills',ci=cats.indexOf(cat);let list=[];if(scope==='Career')list=D.players.map(p=>({name:p.name,value:p.values[ci],detail:p.year==='Unknown'?'Graduation unknown':'Class of '+p.year,url:pLink(p.name)}));else if(scope==='Season'){const groups=new Map();D.stats.forEach(s=>{const key=s.name+'|'+s.season;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s)});list=[...groups.values()].map(rows=>({name:rows[0].name,value:total(rows)[ci],detail:rows[0].season+' season',url:route('player',{id:pByName(rows[0].name).id,season:rows[0].season})}));}else list=D.stats.map(s=>({name:s.name,value:s.values[ci],detail:date(s.date)+' · '+s.opponent,url:route('game',{id:s.id})}));list=list.filter(x=>x.value!=null).sort((a,b)=>b.value-a.value||a.name.localeCompare(b.name));let rank=0,prev;list=list.map((x,i)=>{if(x.value!==prev)rank=i+1;prev=x.value;return {...x,rank}}).filter(x=>x.rank<=10);return `<div class="records-page"><div class="archive-poster"><div><div class="eyebrow">THE AUKS / BY THE NUMBERS</div><h1>Record leaders</h1><p>Career, season, and single-game leaders.<br>Top 10 ranks, with every tie included.</p></div><span class="archive-stamp"><small>TOP</small><strong>10</strong></span></div><div class="tools record-controls">${select('Record scope','scope',['Career','Season','Single game'],scope)}${select('Statistic','category',cats,cat)}</div><p class="record-context">Documented leaders from available results. Historical coverage is incomplete. <a href="#about">About the records ↗</a></p><div class="ranking-heading"><h2>${esc(scope)} ${esc(cat).toLowerCase()}</h2><span>PLAYER / TOTAL</span></div><div class="leader-list record-ranking">${list.map(x=>`<a class="leader-row ${x.rank===1?'record-first':''}" href="${x.url}"><span class="rank"><small>RANK</small>${x.rank.toString().padStart(2,'0')}</span>${jerseyMark(x.name)}<div class="rank-identity"><h3>${esc(x.name)}</h3><small>${esc(x.detail)}</small></div><span class="record-value"><strong>${fmt(x.value)}</strong><small>${esc(cat)}</small></span></a>`).join('')||'<p class="archive-empty">No published statistics available for this category.</p>'}</div><a class="archive-return" href="#players"><span>BEHIND THE NUMBERS</span><strong>Explore the players <b>→</b></strong></a></div>`}

function seasons(){const ys=years();return `<div class="seasons-page"><div class="archive-poster"><div><div class="eyebrow">THE AUKS / SEASON ARCHIVE</div><h1>Season archive</h1><p>Team results, rosters, and the numbers on record.<br>${ys[ys.length-1]}–${ys[0]} · ${ys.length} seasons to explore.</p></div><span class="archive-stamp"><small>SEASONS</small><strong>${ys.length}</strong></span></div><div class="archive-index-title"><h2>Choose a season</h2><span>NEWEST FIRST</span></div><div class="season-grid season-index">${ys.map(y=>{const gs=D.games.filter(g=>g.season===y),w=gs.filter(g=>g.result==='W').length,l=gs.filter(g=>g.result==='L').length,available=gs.filter(g=>g.entries).length;return `<a class="season-ticket" href="${route('season',{year:y})}"><div class="season-ticket-top"><span>${y===ys[0]?'CURRENT SEASON':'FROM THE ARCHIVE'}</span><span aria-hidden="true">↗</span></div><div class="season-ticket-score"><h2>${y}</h2><div><strong>${w}<i>–</i>${l}</strong><small>RECORDED W–L</small></div></div><div class="season-ticket-foot"><span><b>${gs.length}</b> results</span><span><b>${available}/${gs.length}</b> with player stats</span></div></a>`}).join('')}</div><p class="record-context">Records reflect available results, which may not cover a complete season. <a href="#about">Sources & coverage ↗</a></p></div>`}

function season(q){const year=Number(q.get('year'));if(!years().includes(year))return missing('season');const gs=D.games.filter(g=>g.season===year).sort((a,b)=>serial(b.date)-serial(a.date)),rows=D.stats.filter(s=>s.season===year),roster=D.roster.filter(r=>r.season===year),w=gs.filter(g=>g.result==='W').length,l=gs.filter(g=>g.result==='L').length,ys=years(),yi=ys.indexOf(year);return `<div class="season-detail"><a class="back" href="#seasons">← Season archive</a><div class="season-browser">${ys[yi+1]?`<a href="${route('season',{year:ys[yi+1]})}">← ${ys[yi+1]}</a>`:'<span></span>'}${select('Jump to season','year',ys,year)}${ys[yi-1]?`<a href="${route('season',{year:ys[yi-1]})}">${ys[yi-1]} →</a>`:'<span></span>'}</div><div class="archive-poster"><div><div class="eyebrow">ARCHMERE / GIRLS VARSITY</div><h1>${year} season</h1><p>${gs.length} available results · ${roster.length?roster.filter(r=>r.role!=='Manager').length+' rostered players':'Roster unavailable'}</p></div><span class="archive-stamp season-record-stamp"><small>RECORDED W–L</small><strong>${w}–${l}</strong></span></div><div class="season-jumps" aria-label="Season sections"><button type="button" data-season-jump="season-roster">Roster ↓</button><button type="button" data-season-jump="season-leaders">Leaders ↓</button><button type="button" data-season-jump="season-matches">Matches ↓</button></div>${coveragePanel(gs)}<section class="season-totals"><h2>Documented season totals</h2>${statstrip(total(rows))}<p>${gs.filter(g=>g.entries).length} of ${gs.length} result pages have usable player statistics. Missing stats are not counted as zero.</p></section><section class="section" id="season-roster"><div class="archive-index-title"><h2>The ${year} roster</h2><span>PLAYER RECORDS ↗</span></div><div class="season-roster">${roster.map(r=>`<a href="${pLink(r.name)}"><span class="season-roster-number">${r.role==='Manager'?'MGR':r.jersey?'#'+esc(r.jersey):'—'}</span><span><strong>${esc(r.name)}</strong><small>${r.role==='Manager'?'Manager':r.grade?'Grade '+esc(r.grade):'Varsity'} · ${year}</small></span><span aria-hidden="true">↗</span></a>`).join('')||'<p class="archive-empty">No archived roster is available for this season.</p>'}</div></section>${seasonLeaders(rows,year)}<section class="section" id="season-matches"><div class="archive-index-title"><h2>The matches</h2><span>NEWEST FIRST</span></div><div class="game-list">${gs.map(gameCard).join('')}</div></section></div>`}

function about(){return `<div class="editorial-heading"><div class="eyebrow">THE RECORD BOOK / SOURCES & COVERAGE</div><h1>Behind the numbers</h1><p>How this archive was built, what’s included, and where the gaps remain.</p></div><div class="about-grid"><section class="card"><h2>What’s included</h2><p>${D.games.length} result pages across the 2006–2026 archive, ${D.players.length} listed players and ${fmt(D.stats.length)} published player-game entries. Varsity regular-season and postseason records are included.</p><p>Updated ${D.updated}. This is a snapshot, not a live connection to Google Sheets. New records and corrections require a site update.</p></section><section class="card"><h2>Read the stats fairly</h2><p>${D.games.filter(g=>g.entries).length} games have usable Archmere player statistics; ${D.games.filter(g=>!g.entries).length} have scores without usable player stats. A dash means unreported. Zero means a published zero. Source rows may include nonparticipants and are not a games-played count.</p><p><a href="${route('games',{coverage:'Missing player stats'})}">Explore games with missing stats ↗</a></p></section><section class="card"><h2>Sources & method</h2><p>Each archived season was selected on AuksSports and each available View Results link was opened. Player tables and written summaries were reconciled against seasonal rosters. Every game retains its original result link.</p><p><a href="https://www.aukssports.com/teams/gvb/teamstats" target="_blank" rel="noopener noreferrer">Visit AuksSports ↗</a></p></section></div><section class="section"><h2>Entries held for review</h2><a class="button review-open" href="#review">Review questioned results →</a><p class="intro">${D.issues.length} ambiguous or incomplete stat lines are excluded from numeric totals. No missing categories have been guessed.</p><div class="stack section">${D.issues.map(i=>`<details class="card"><summary>${esc(i.name||'Source entry')} · ${esc(i.season)}</summary><p>${esc(i.reason)}</p><p class="quiet">${esc(i.raw)}</p>${source(i.source)}</details>`).join('')}</div></section><p class="note">This independent record book is not an official school publication. Historical gaps mean totals should not be presented as certified all-time school records.</p>`}
function missing(what){return `<h1>That ${what} wasn’t found.</h1><p class="intro">Return to the record book to continue browsing.</p><a class="button section" href="#home">Back to home</a>`}
function roster(){const year=Math.max(...D.roster.map(r=>r.season));const list=D.roster.filter(r=>r.season===year&&r.role!=='Manager').sort((a,b)=>Number(a.jersey)-Number(b.jersey));return `<section class="roster-heading"><div><div class="eyebrow">ARCHMERE / GIRLS VARSITY</div><h1>Current roster</h1><p>${list.length} players. One team.<br>Tap a player for career stats and game results.</p></div><div class="roster-year"><span>CURRENT ROSTER</span><strong>${year}</strong><small>ARCHMERE VOLLEYBALL</small></div></section><div class="chips section"><a class="chip" href="${route('season',{year})}">${year} season overview →</a><a class="chip" href="${route('games',{season:year})}">Season results →</a></div><div class="player-grid section">${list.map(r=>{const p=pByName(r.name);return `<a class="card player-card" href="${pLink(r.name)}"><div class="top">${jerseyMark(r.name)}<div><h3>${esc(r.name)}</h3><small>Grade ${esc(r.grade)}${p&&p.year!=='Unknown'?' · Class of '+p.year:''}</small></div><span class="arrow" aria-hidden="true">↗</span></div><p class="quiet">${year} season totals</p>${statstrip(total(D.stats.filter(s=>s.name===r.name&&s.season===year)))}</a>`}).join('')}</div>${note()}<p class="quiet section">Roster snapshot updated ${D.updated}. <a href="https://www.aukssports.com/teams/gvb/roster" target="_blank" rel="noopener noreferrer">School roster ↗</a></p>`}
const reviewStorageKey='archmere-review-v1';
function reviewKey(issue){return JSON.stringify([issue.id,issue.season,issue.name,issue.raw]);}
function readReviews(){try{return JSON.parse(localStorage.getItem(reviewStorageKey)||'{}')}catch{return {}}}
function reviewPlayerRow(row={name:'',values:[]}){return `<div class="review-player-row"><label>Player name<input name="review-name" list="review-player-names" value="${esc(row.name)}" placeholder="Choose the exact player name" autocomplete="off"></label><div class="review-values">${cats.map((c,i)=>`<label>${c}<input type="number" name="review-value" min="0" step="1" inputmode="numeric" value="${row.values?.[i]??''}" placeholder="—"></label>`).join('')}</div><button type="button" class="review-remove">Remove row</button></div>`;}
function resolvedReviews(items=D.resolvedIssues||[]){return items.length?`<section class="section resolved-reviews"><h2>Resolved reviews</h2>${items.map(i=>`<details class="card"><summary>${i.decision==='exclude'?'Resolved — kept excluded':'Resolved'} · ${esc(i.season)} · ${i.name==='Team labels disputed'?'Team labels corrected':esc(i.name)}</summary><p>${esc(i.explanation)}</p><p>Applied ${esc(i.resolvedAt)} · ${i.decision==='exclude'?'Excluded from numeric totals.':'Included in published totals.'}</p><div class="review-source-actions"><a href="${route('game',{id:i.id})}">Game record →</a>${source(i.source,'Original result')}</div><p>${i.evidence.map(e=>`<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.label)} ↗</a>`).join(' · ')}</p>${i.rows.length?`<h3>Applied Archmere entries</h3>${boxRows(i.rows)}`:''}<details><summary>Original source text</summary><p>${esc(i.raw)}</p></details></details>`).join('')}</section>`:'';}
function review(){const saved=readReviews();if(!D.issues.length)return `<div class="review-page"><div class="editorial-heading"><div class="eyebrow">THE RECORD BOOK / REVIEW DESK</div><h1>Review complete.</h1><p>All flagged entries in this snapshot have a published decision.</p></div><div class="review-overview"><p><strong>0 pending · ${(D.resolvedIssues||[]).length} resolved</strong></p></div><p class="review-explanation">Corrections are included in the player, season and record totals. Entries marked “kept excluded” remain outside numeric totals. Unreported categories still show a dash.</p>${resolvedReviews()}</div>`;return `<div class="review-page"><div class="editorial-heading"><div class="eyebrow">THE RECORD BOOK / REVIEW DESK</div><h1>Check the record.</h1><p>Review questioned source entries before they become part of the published totals.</p></div><div class="review-overview"><p><strong id="review-progress">${D.issues.filter(i=>saved[reviewKey(i)]?.decision&&saved[reviewKey(i)].decision!=='pending').length} of ${D.issues.length}</strong> entries reviewed on this device.</p><button type="button" class="button" id="review-export">Export decisions ↓</button></div><p class="review-explanation">Open the official result, check the original text, then save a decision. Leave unknown stats blank; enter 0 only when the source supports zero. Saved decisions stay in this browser and do not change the public totals. Export them and send the file here to apply reviewed corrections.</p><div class="review-filter"><label>Show<select id="review-status-filter"><option value="all">All entries</option><option value="pending">Needs review</option><option value="correction">Verified correction</option><option value="exclude">Keep excluded</option></select></label><label>Season<select id="review-season-filter"><option value="all">All seasons</option>${[...new Set(D.issues.map(i=>i.season))].sort((a,b)=>a-b).map(y=>`<option value="${y}">${y}</option>`).join('')}</select></label></div><p id="review-visible-count" class="count">${D.issues.length} entries shown</p><datalist id="review-player-names">${D.players.map(p=>`<option value="${esc(p.name)}"></option>`).join('')}</datalist><div class="review-queue">${D.issues.map((issue,index)=>{const record=saved[reviewKey(issue)]||{},status=record.decision||'pending',g=D.games.find(g=>g.id===String(issue.id)),rows=record.rows?.length?record.rows:[{name:pByName(issue.name)?issue.name:'',values:[]}];return `<details class="review-entry" data-issue="${index}" data-status="${status}" data-season="${issue.season}"><summary><span class="review-entry-number">${String(index+1).padStart(2,'0')}</span><span><strong>${esc(issue.name)}</strong><small>${issue.season}${g?' · '+esc(g.opponent):''}</small></span><span class="review-status">${status==='correction'?'Correction saved':status==='exclude'?'Kept excluded':'Needs review'}</span></summary><div class="review-entry-body"><p class="review-reason">${esc(issue.reason)}</p><div class="review-source-actions">${source(issue.source,'Open official result')}<a href="${route('game',{id:issue.id})}">Current game record ↗</a></div><h3>Original source text</h3><pre>${esc(issue.raw)}</pre><form class="review-form" data-review-index="${index}"><label>Decision<select name="decision"><option value="pending" ${status==='pending'?'selected':''}>Needs more evidence</option><option value="exclude" ${status==='exclude'?'selected':''}>Keep excluded</option><option value="correction" ${status==='correction'?'selected':''}>Verified correction</option></select></label><div class="review-correction" ${status!=='correction'?'hidden':''}><p>Enter only the player rows you can verify. All five categories are shown in record-book order. For a team-label dispute, add each confirmed Archmere player separately.</p><div class="review-rows">${rows.map(reviewPlayerRow).join('')}</div><button type="button" class="button review-add">+ Add player row</button></div><label>Evidence / notes<textarea name="notes" rows="3" placeholder="Explain what confirms the correction or why this must remain excluded. Include an additional source link if needed.">${esc(record.notes||'')}</textarea></label><button class="button review-save" type="submit">Save decision</button> <button class="button review-clear" type="button">Clear decision</button><p class="review-save-message" role="status">${record.updatedAt?'Saved on this device.':''}</p></form></div></details>`}).join('')}</div>${resolvedReviews()}<p class="note">A saved correction is a review decision, not an automatic edit. Original source text and the reason it was withheld stay attached to every exported entry.</p></div>`;}
function filterReview(){const status=$('#review-status-filter').value,season=$('#review-season-filter').value;let count=0;document.querySelectorAll('.review-entry').forEach(el=>{el.hidden=(status!=='all'&&el.dataset.status!==status)||(season!=='all'&&el.dataset.season!==season);if(!el.hidden)count++});$('#review-visible-count').textContent=count+' entries shown';}
document.addEventListener('change',e=>{if(e.target.matches('#review-status-filter,#review-season-filter'))filterReview();if(e.target.matches('.review-form select[name=decision]'))e.target.closest('form').querySelector('.review-correction').hidden=e.target.value!=='correction';});
document.addEventListener('click',e=>{if(e.target.closest('.review-add')){e.target.closest('form').querySelector('.review-rows').insertAdjacentHTML('beforeend',reviewPlayerRow());}if(e.target.closest('.review-remove')){e.target.closest('.review-player-row').remove();}if(e.target.closest('#review-export')){const saved=readReviews(),decisions=D.issues.map(i=>saved[reviewKey(i)]).filter(Boolean);if(!decisions.length){toast('Save at least one review decision first.');return}const payload={schema:'archmere-review-v1',sourceSnapshot:D.updated,exportedAt:new Date().toISOString(),decisions},url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='archmere-reviewed-results.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Review decisions exported.');}});
document.addEventListener('submit',e=>{const form=e.target.closest('.review-form');if(!form)return;e.preventDefault();const issue=D.issues[Number(form.dataset.reviewIndex)],decision=form.elements.decision.value,notes=form.elements.notes.value.trim(),message=form.querySelector('.review-save-message'),rows=[...form.querySelectorAll('.review-player-row')].map(el=>({name:el.querySelector('[name=review-name]').value.trim(),values:[...el.querySelectorAll('[name=review-value]')].map(input=>input.value===''?null:Number(input.value))}));if(decision==='correction'){if(!notes){message.textContent='Add evidence explaining how you verified this correction.';return}if(!rows.length||rows.some(r=>!pByName(r.name)||r.values.every(v=>v==null)||r.values.some(v=>v!=null&&(!Number.isInteger(v)||v<0)))){message.textContent='Use an exact player name and at least one verified non-negative whole-number stat in each row.';return}if(new Set(rows.map(r=>r.name)).size!==rows.length){message.textContent='Each player should appear once in this correction.';return}}const saved=readReviews();saved[reviewKey(issue)]={gameId:issue.id,season:issue.season,issueName:issue.name,originalRaw:issue.raw,reason:issue.reason,source:issue.source,decision,notes,rows:decision==='correction'?rows:[],updatedAt:new Date().toISOString()};try{localStorage.setItem(reviewStorageKey,JSON.stringify(saved))}catch{message.textContent='This browser could not save the review. Enable local storage and try again.';return}const entry=form.closest('.review-entry');entry.dataset.status=decision;entry.querySelector('.review-status').textContent=decision==='correction'?'Correction saved':decision==='exclude'?'Kept excluded':'Needs review';message.textContent='Saved on this device. Public totals are unchanged.';$('#review-progress').textContent=D.issues.filter(i=>saved[reviewKey(i)]?.decision&&saved[reviewKey(i)].decision!=='pending').length+' of '+D.issues.length;});
const REPO='nitrogoal/archmere-volleyball',UPDATER='update-from-source.yml';
const todayET=()=>serial(new Date().toLocaleDateString('en-US',{timeZone:'America/New_York'}));
const offStatus=s=>/^(postponed|cancel+ed)$/i.test(s.status||'');
// Same score + W/L badge as the game cards.
const wl=(result,score)=>`${esc(score)} <span class="badge ${result==='L'?'loss':''}">${esc(result)}</span>`;
let lastCheck;
async function sourceChecked(){if(lastCheck!==undefined)return lastCheck;try{const c=JSON.parse(sessionStorage.getItem('auksvb-checked')||'null');if(c&&Date.now()-c.at<6e5)return lastCheck=c.when}catch{}try{const r=await fetch(`https://api.github.com/repos/${REPO}/actions/workflows/${UPDATER}/runs?status=success&per_page=1`);const when=r.ok?(await r.json()).workflow_runs?.[0]?.updated_at||null:null;try{sessionStorage.setItem('auksvb-checked',JSON.stringify({at:Date.now(),when}))}catch{}return lastCheck=when}catch{return lastCheck=null}}
function fillChecked(){const el=$('[data-source-checked]');if(!el)return;sourceChecked().then(when=>{if(!when||!el.isConnected)return;const d=new Date(when),same=d.toLocaleDateString('en-US',{timeZone:'America/New_York'})===new Date().toLocaleDateString('en-US',{timeZone:'America/New_York'});el.textContent='Source checked '+(same?'today':d.toLocaleDateString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric'}))+', '+d.toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'})+' · ';el.hidden=false})}
const crest=(name)=>`<span class="logo">${name==='Archmere'?'<img src="archmere-auks.jpg" alt="">':opponentMark(name)}</span>`;
const shortName=n=>n.replace(/\s+(HS|School|Academy)$/,'');
const mapLink=loc=>`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(loc)}`;
const scoreBadge=(g)=>`<span class="sc-score">${esc(g.score)} <span class="badge ${g.result==='L'?'loss':''}">${esc(g.result)}</span></span>`;
function upcomingMatches(){const year=Math.max(...D.roster.map(r=>r.season)),t=todayET();return (D.currentSchedule||[]).filter(s=>s.season===year&&s.kind==='Match'&&!s.gameId&&!offStatus(s)&&serial(s.date)>=t).sort((a,b)=>serial(a.date)-serial(b.date))}
function daysTo(s){return Math.round((serial(s.date)-todayET())/864e5)}
function countLabel(d){return d===0?'Game day':d===1?'Day until':'Days until'}
function nextMatch(){const up=upcomingMatches()[0];if(!up)return '';const dt=new Date(serial(up.date)),home=up.homeAway==='H',days=daysTo(up);
 return `<a class="next bleed" href="#schedule" aria-label="Next match: ${home?'vs':'at'} ${esc(up.opponent)}, ${dt.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}, ${esc(up.time||'time TBD')}. Open the schedule."><span class="n-word" aria-hidden="true">${days===0?'Game day':'Next up'}</span><div class="wrap" aria-hidden="true"><span class="n-count">${days===0?'Today':days}</span><span class="until">${countLabel(days)}<i>we play ${esc(shortName(up.opponent))}</i></span><span class="next-opp"><span class="n-face">${crest('Archmere')}<span class="vs">${home?'VS':'AT'}</span>${crest(up.opponent)}</span><span class="n-info"><b>${esc(up.opponent)}</b><span class="n-tags"><span>${dt.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}</span><span>${esc(up.time||'Time TBD')}</span><span>${home?'Home':'Away'}</span>${up.notes?`<span class="hot">${esc(up.notes)}</span>`:''}${themeFor(up)?`<span class="hot theme">${esc(themeFor(up))} night</span>`:''}${up.streamUrl?'<span class="live">● Live on NFHS</span>':''}</span></span></span><span class="n-btn">Schedule →</span></div></a>`}
function schedule(q){
 const year=Math.max(...D.roster.map(r=>r.season)),today=todayET(),off=offStatus;
 const rows=(D.currentSchedule||[]).filter(s=>s.season===year).map(s=>({...s,game:D.games.find(g=>g.season===year&&(s.gameId===g.id||(s.kind==='Match'&&s.date===g.date&&s.opponent===g.opponent)))}));
 for(const g of D.games.filter(g=>g.season===year))if(!rows.some(s=>s.game?.id===g.id))rows.push({...g,kind:'Match',game:g});
 for(const s of D.scheduleOnly.filter(s=>s.season===year))if(!rows.some(r=>r.date===s.date&&r.opponent===s.opponent))rows.push({...s,kind:'Match'});
 const isUp=s=>s.kind==='Match'&&!s.game&&!off(s)&&serial(s.date)>=today;
 const upcoming=rows.filter(isUp).sort((a,b)=>serial(a.date)-serial(b.date));
 const results=rows.filter(s=>s.kind==='Match'&&!isUp(s)).sort((a,b)=>serial(b.date)-serial(a.date));
 const team=rows.filter(s=>s.kind!=='Match').sort((a,b)=>serial(a.date)-serial(b.date));
 const W=results.filter(s=>s.game?.result==='W').length,L=results.filter(s=>s.game?.result==='L').length,show=q.get('show')||'';
 const next=upcoming[0],days=next?daysTo(next):0;
 const card=s=>{const d=new Date(serial(s.date)),g=s.game,isTeam=s.kind!=='Match',home=s.homeAway==='H';
  const status=g?'':off(s)?esc(s.status):isTeam?'':isUp(s)?'Upcoming':'Result pending';
  return `<article class="game ${isTeam?'event':''}"><div class="d"><span>${d.toLocaleDateString('en-US',{month:'short'})} · ${d.toLocaleDateString('en-US',{weekday:'short'})}</span><b>${d.getDate()}</b><small>${esc(s.time||'TBD')}</small></div>${isTeam&&s.kind==='Team event'?'<span class="logo"><img src="archmere-auks.jpg" alt=""></span>':crest(s.opponent)}<div class="info"><span class="tag ${home?'':'away'}">${isTeam?esc(s.kind):home?'Home':s.homeAway==='A'?'Away':'Neutral'}</span><b>${isTeam?esc(s.opponent):`<a class="opp-link" href="${route('opponent',{name:s.opponent})}">${esc(s.opponent)}</a>`}</b><small>${esc(s.location||'Location to be confirmed')}</small><span class="tags">${s.notes?`<span class="pill">${esc(s.notes)}</span>`:''}${themePill(s)}${isUp(s)?liveLink(s):''}</span></div><div class="res">${g?`${scoreBadge(g)}<a href="${route('game',{id:g.id})}">Box score →</a>${source(g.url,'Official')}`:status?`<span class="soon">${status}</span>`:''}${isUp(s)?calMenu(s):''}${!g&&isTeam&&s.url?source(s.url,'Details ↗'):''}</div></article>`};
 const feature=s=>{const d=new Date(serial(s.date)),home=s.homeAway==='H';return `<article class="feature" aria-label="Next game"><span class="f-art" aria-hidden="true"><span class="f-word">${days===0?'Game day':'Next up'}</span></span><div class="f-count"><b>${days===0?'Today':days}</b><span>${days===0?'Game day':days===1?'Day to go':'Days to go'}</span></div><span class="f-kicker">Next up · ${home?'Home':'Away'}<i>let's go Auks</i></span><div class="f-teams">${crest('Archmere')}<span class="vs">${home?'VS':'AT'}</span>${crest(s.opponent)}<h3>${esc(s.opponent)}</h3></div><div class="f-meta"><span>${d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}</span><span>${esc(s.time||'Time TBD')}</span><span>${esc(s.location||'Location TBD')}</span>${s.notes?`<span class="pill">${esc(s.notes)}</span>`:''}${themeFor(s)?`<span class="theme-pill">${esc(themeFor(s))} night</span>`:''}${liveLink(s)}<span class="f-actions">${calMenu(s)}${s.location?`<a class="f-dir" href="${mapLink(s.location)}" target="_blank" rel="noopener noreferrer">Directions ↗</a>`:''}</span></div>${h2hLink(s.opponent)}</article>`};
 const pills=[['','All'],['Upcoming','Upcoming'],['Results','Results'],['Team dates','Team dates']].map(([v,n])=>`<a class="${show===v?'on':''}" href="${v?route('schedule',{show:v}):'#schedule'}" ${show===v?'aria-current="true"':''}>${n}</a>`).join('');
 const sec=(title,sub,body)=>body?`<h2 class="month">${title}<span>${sub}</span></h2>${body}`:'';
 const upBody=upcoming.length?(next?feature(next):'')+upcoming.slice(1).map(card).join(''):'';
 const parts=[(!show||show==='Upcoming')?sec('Up next',`${upcoming.length} remaining`,upBody):'',(!show||show==='Results')?sec('Results','Most recent first',results.map(card).join('')):'',(!show||show==='Team dates')?sec('Preseason &amp; team dates','Not counted in records',team.map(card).join('')):''].join('');
 return `<section class="pg-head bleed" data-word="Schedule"><div class="wrap"><div><span class="label">The Auks · ${year} varsity</span><h1>Schedule</h1></div><div class="meta"><b>${W}–${L}</b>${rows.filter(s=>s.kind==='Match').length} matches · ${upcoming.length} to play</div></div></section><div class="stripe bleed"></div><div class="seg">${pills}</div><div class="sched-actions">${subscribeMenu()}<a class="seg-link" href="https://www.aukssports.com/page9857" target="_blank" rel="noopener noreferrer">Official schedule ↗</a></div><p class="count-line">All times Eastern · <span data-source-checked hidden></span>Results updated ${esc(D.updated)} · Dates and times may change.</p>${parts||'<p class="empty">No dates in this view.</p>'}<p class="note">Scrimmages and team dates are listed for convenience and do not count toward season records or player statistics.</p>`;
}
function navFit(){const n=$('#nav'),a=n.querySelector('.active');if(a){const l=a.offsetLeft-n.offsetLeft;n.scrollLeft=l+a.offsetWidth+24<=n.clientWidth?0:l-(n.clientWidth-a.offsetWidth)/2}navEdge()}
function navEdge(){const n=$('#nav');n.classList.toggle('more-right',n.scrollLeft+n.clientWidth<n.scrollWidth-2);n.classList.toggle('more-left',n.scrollLeft>2)}
const pages={home,roster,players,player,games,game,records,seasons,season,about,review,schedule};
function render(reset=true){if(!D)return;const {page,q}=getState();document.body.dataset.page=page;const active=page==='player'?'players':page==='game'||page==='opponent'?'games':page==='season'?'seasons':page;const navItems=[['home','Home'],['schedule','Schedule'],['roster','Roster'],['players','Players'],['games','Results'],['records','Records'],['seasons','Seasons']],primary=['home','schedule','roster','games'],extra=navItems.filter(([id])=>!primary.includes(id)),extraActive=extra.find(([id])=>id===active);
 // Phones show four primary tabs plus a "More" menu; desktop shows every tab in one row.
 $('#nav').innerHTML=navItems.map(([id,label])=>`<a class="${active===id?'active':''} ${primary.includes(id)?'':'nav-extra'}" href="#${id}" ${active===id?'aria-current="page"':''}>${label}</a>`).join('')+`<button type="button" class="nav-more ${extraActive?'active':''}" aria-expanded="false" aria-controls="nav-sheet">${extraActive?extraActive[1]:'More'}<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M2 4.5l4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.8"/></svg></button><div class="nav-sheet" id="nav-sheet" hidden>${[...extra,['about','Sources & coverage']].map(([id,label])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${esc(label)}<span aria-hidden="true">→</span></a>`).join('')}</div>`;$('#main').innerHTML=(pages[page]||home)(q);const p=page==='player'?D.players.find(p=>p.id===q.get('id')):null;const ph=$('#main').querySelector('.roster-heading,.directory-heading,.games-heading,.archive-poster,.editorial-heading,.result-heading');if(ph&&!ph.dataset.word){const h=ph.querySelector('h1');if(h)ph.dataset.word=h.textContent.trim().split(/\s+/).pop()}fillChecked();document.title=page==='home'?'Archmere Volleyball':(p?p.name:page==='opponent'?(q.get('name')||'Opponent'):page==='games'?'Results':page[0].toUpperCase()+page.slice(1))+' · Archmere Volleyball';navFit();if(reset)window.scrollTo(0,0);}
document.addEventListener('change',e=>{if(e.target.matches('[data-filter]'))updateFilter(e.target,false)});
function setNavSheet(open,focusButton){const sheet=$('#nav-sheet'),btn=$('.nav-more');if(!sheet||!btn)return;sheet.hidden=!open;btn.setAttribute('aria-expanded',String(open));if(open)sheet.querySelector('a')?.focus();else if(focusButton)btn.focus()}
document.addEventListener('click',e=>{if(e.target.closest('.nav-more')){setNavSheet($('#nav-sheet').hidden);return}if(e.target.closest('#nav-sheet a')||!e.target.closest('#nav-sheet'))setNavSheet(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#nav-sheet')&&!$('#nav-sheet').hidden)setNavSheet(false,true)});
let searchTimer;document.addEventListener('input',e=>{if(e.target.matches('input[data-filter]')){clearTimeout(searchTimer);searchTimer=setTimeout(()=>updateFilter(e.target,true),180)}});
function updateFilter(input,focus){const {page,q}=getState(),key=input.dataset.filter,value=input.value,position=input.selectionStart;if(value)q.set(key,value);else q.delete(key);history.replaceState(null,'',route(page,Object.fromEntries(q)));render(false);if(focus){const el=$('#search');el?.focus();if(position!=null)el?.setSelectionRange(position,position)}}
window.addEventListener('hashchange',()=>render());
$('#nav').addEventListener('scroll',navEdge,{passive:true});window.addEventListener('resize',navFit);
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();});
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
$('#share').addEventListener('click',async()=>{const data={title:document.title,url:location.href};try{if(navigator.share){await navigator.share(data);return}await navigator.clipboard.writeText(location.href);toast('Link copied. Ready to share!')}catch(e){if(e.name!=='AbortError')prompt('Copy this link to share:',location.href)}});
Promise.all([fetch('data.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}),fetch('opponents.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]).then(([d,logos])=>{D=d;teamLogos=logos;render()}).catch(()=>{$('#main').innerHTML='<div class="empty"><h1>Couldn’t load the record book.</h1><p>Please refresh the page to try again.</p></div>'});

document.addEventListener('error',e=>{if(e.target.matches?.('.opponent-mark img')){e.target.hidden=true;e.target.previousElementSibling.hidden=false;}},true);
document.addEventListener('click',e=>{if(!e.target.closest('.review-clear'))return;const form=e.target.closest('.review-form'),issue=D.issues[Number(form.dataset.reviewIndex)],saved=readReviews();delete saved[reviewKey(issue)];try{localStorage.setItem(reviewStorageKey,JSON.stringify(saved))}catch{form.querySelector('.review-save-message').textContent='Unable to clear the saved review.';return}form.elements.decision.value='pending';form.elements.notes.value='';form.querySelector('.review-rows').innerHTML=reviewPlayerRow({name:pByName(issue.name)?issue.name:'',values:[]});form.querySelector('.review-correction').hidden=true;const entry=form.closest('.review-entry');entry.dataset.status='pending';entry.querySelector('.review-status').textContent='Needs review';form.querySelector('.review-save-message').textContent='Decision cleared. This entry needs review.';$('#review-progress').textContent=D.issues.filter(i=>saved[reviewKey(i)]?.decision&&saved[reviewKey(i)].decision!=='pending').length+' of '+D.issues.length;});
